class Solution:
    def distanceBetweenBusStops(self, distance: List[int], start: int, destination: int) -> int:
        n = len(distance)

        def walk(a, b, step):
            total = 0
            while a != b:
                total += distance[a]
                a = (a + step) % n
            return total

        return min(walk(start, destination, 1), walk(start, destination, -1))

