class Solution {
public:
    int distanceBetweenBusStops(vector<int>& distance, int start, int destination) {
        int n = distance.size();
        auto walk = [&](int a, int b, int step) {
            long long total = 0;
            while (a != b) {
                total += distance[a];
                a = ((a + step) % n + n) % n;
            }
            return total;
        };
        return (int)min(walk(start, destination, 1), walk(start, destination, -1));
    }
};

