class Solution {
    public int distanceBetweenBusStops(int[] distance, int start, int destination) {
        int n = distance.length;
        return Math.min(walk(distance, start, destination, 1),
                        walk(distance, start, destination, -1));
    }

    private long walk(int[] d, int a, int b, int step) {
        int n = d.length;
        long total = 0;
        while (a != b) {
            total += d[a];
            a = ((a + step) % n + n) % n;
        }
        return total;
    }
}

